  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return ctx.begin();
  }

  template <typename FormatContext>
  auto format(const tuple_join_view<Char, T...>& value, FormatContext& ctx) ->
      typename FormatContext::iterator {
    remaining_ = sizeof...(T);
    emit_separator_ = remaining_ > 1;
    return format(value, ctx, detail::make_index_sequence<sizeof...(T)>{});
  }

 private:
  template <typename FormatContext, size_t... N>
  auto format(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
              detail::index_sequence<N...>) ->
      typename FormatContext::iterator {
    using std::get;
    return format_args(value, ctx, get<N>(value.tuple)...);
  }

  template <typename FormatContext>
  auto format_args(const tuple_join_view<Char, T...>&, FormatContext& ctx) ->
      typename FormatContext::iterator {
    // NOTE: for compilers that support C++17, this empty function instantiation
    // can be replaced with a constexpr branch in the variadic overload.
    return ctx.out();
  }

  template <typename FormatContext, typename Arg, typename... Args>
  auto format_args(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
                   const Arg&, const Args&... args) ->
      typename FormatContext::iterator {
    using std::get;
    const auto& selected =
        get<sizeof...(T) - sizeof...(Args) - 1>(value.tuple);
    using base = formatter<typename std::decay<Arg>::type, Char>;
    auto out = base().format(selected, ctx);
    if (remaining_ > 0) --remaining_;
    if (sizeof...(Args) > 0) {
      const auto& sep = value.separator;
      emit_separator_ = remaining_ > 0;
      if (emit_separator_) {
        if (!sep.empty && sep.size == 1) {
          *out++ = sep.first;
        } else {
          out = detail::copy_join_separator(out, sep.data, sep.end);
        }
      }
      ctx.advance_to(out);
      return format_args(value, ctx, args...);
    }
    return out;
  }
};

